package com.chatsystem.user.controller.social;
import com.chatsystem.shared.model.FriendRequest;import com.chatsystem.shared.service.SocialService;import com.chatsystem.user.navigation.*;import com.chatsystem.user.ui.cell.FriendRequestCell;import javafx.fxml.FXML;import javafx.scene.control.*;
public final class FriendRequestsController{private final SocialService social;private final UserNavigator nav;@FXML private ListView<FriendRequest> incomingList,outgoingList;@FXML private Label requestFeedbackLabel;public FriendRequestsController(SocialService s,UserNavigator n){social=s;nav=n;}@FXML private void initialize(){incomingList.setItems(social.getIncomingRequests());outgoingList.setItems(social.getOutgoingRequests());incomingList.setCellFactory(x->new FriendRequestCell());outgoingList.setCellFactory(x->new FriendRequestCell());}@FXML private void accept(){run(incomingList,social::acceptRequest,"Request accepted");}@FXML private void decline(){run(incomingList,social::rejectRequest,"Request declined");}@FXML private void cancel(){run(outgoingList,social::cancelRequest,"Request cancelled");}@FXML private void back(){nav.navigate(ViewRequest.of(UserRoute.FRIENDS));}private void run(ListView<FriendRequest> l,java.util.function.LongFunction<com.chatsystem.shared.validation.ValidationResult<Void>> f,String ok){var r=l.getSelectionModel().getSelectedItem();if(r==null){requestFeedbackLabel.setText("Choose a request");return;}var result=f.apply(r.getId());requestFeedbackLabel.setText(result.isSuccess()?ok:result.errors().get(0).message());}}
